// Кейс: .qa/tests/monitoring/MON-027.md (шаги 3–4) · план: .qa/e2e-app/specs/app.md (1.38)
// Один телефон: «בדיקת בטיחות» (4 מתוך 5) → шаг 2 → шаг 3 «מי בבריכה היום?» → «התחלת ניטור» → «תקין», «זמן ניטור» идёт.
// РУЧНОЕ ПРЕДУСЛОВИЕ: второй телефон удалён (BANCI_ONE_PHONE=1); запускает мониторинг — только с BANCI_MONITORING=1 (@data).
import { by, assert, skip } from '../../lib/appium.mjs';
import { requireMonitoringOptIn, startMonitoring, timerSeconds, waitTimer, endMonitoring } from '../../lib/monitoring.mjs';

export const name = 'Один телефон в аккаунте: мониторинг стартует, «תקין», «זמן ניטור» идёт (BANCI_ONE_PHONE) #4a869b @iphone @app @data';

export default async function (app) {
  if (process.env.BANCI_ONE_PHONE !== '1') skip('второй телефон удаляется вручную: удалить и запустить с BANCI_ONE_PHONE=1; после — вернуть по QR (DEV-012)');
  requireMonitoringOptIn();

  await startMonitoring(app); // внутри: «המשך» на «בדיקת בטיחות» должна стать активной при 4 מתוך 5
  const t0 = await timerSeconds(app);
  const t1 = await waitTimer(app, t0 + 5, { timeout: 30000 });
  assert(t1 > t0, `«זמן ניטור» идёт: было ${t0} с, стало ${t1} с`);
  assert(await app.exists(by.exact('תקין')), 'статус «תקין» на экране мониторинга');
  await app.screenshot('4a869b-auto-monitoring-one-phone');
  await endMonitoring(app);
}
